def icon(name, cls="ico", label=None):
    """Inline SVG. Decorative unless a label is given."""
    body = _PATHS[name]
    aria = f' role="img" aria-label="{escape(label)}"' if label else ' aria-hidden="true"'
    return (
        f'<svg class="{cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
        f'stroke-linecap="round" stroke-linejoin="round"{aria}>{body}</svg>'
    )


def names():
    return tuple(_PATHS)
